* MNDU - The Mandelbrot fractal utility.
* Based on 'CONS1'.
MAP MNDU1 SIZE 24x80
  FIELD AT 0,0   LEN 30 PROT BRIGHT COLOR=BLUE   "MNDU - The Mandelbrot Fractal UTILITY!"
  INPUT TERMID   AT 0,65  LEN 8  PROT COLOR=BLUE
  FIELD AT 0,60  LEN 5  PROT COLOR=BLUE          "TERM="
  FIELD AT 2,0   LEN 12 PROT COLOR=WHITE         "Import/Export"
  FIELD AT 3,0   LEN 12 PROT                     "Import File:"
  INPUT NIMPORT  AT 3,20  LEN 20 UNDERSCORE COLOR=GREEN
  STOP           AT 3,41
  FIELD AT 4,0   LEN 12 PROT                     "Export File:"
  INPUT NEXPORT  AT 4,20  LEN 16 UNDERSCORE COLOR=GREEN
  STOP           AT 4,41

  INPUT STATUS   AT 6,0  LEN 20  PROT COLOR=WHITE
  FIELD AT 7,0   LEN 78 PROT DIM COLOR=TURQUOISE    "D NAME             NOTE"
  FIELD ROW1     AT 8,2   LEN 70 PROT COLOR=GREEN
  FIELD ROW2     AT 9,2   LEN 70 PROT COLOR=GREEN
  FIELD ROW3     AT 10,2  LEN 70 PROT COLOR=GREEN
  FIELD ROW4     AT 11,2  LEN 70 PROT COLOR=GREEN
  FIELD ROW5     AT 12,2  LEN 70 PROT COLOR=GREEN
  FIELD ROW6     AT 13,2  LEN 70 PROT COLOR=GREEN
  FIELD ROW7     AT 14,2  LEN 70 PROT COLOR=GREEN
  FIELD ROW8     AT 15,2  LEN 70 PROT COLOR=GREEN
  FIELD ROW9     AT 16,2  LEN 70 PROT COLOR=GREEN
  FIELD ROW10    AT 17,2  LEN 70 PROT COLOR=GREEN
  INPUT DEL1     AT 8,0   LEN 1 COLOR=RED
  INPUT DEL2     AT 9,0   LEN 1 COLOR=RED
  INPUT DEL3     AT 10,0  LEN 1 COLOR=RED
  INPUT DEL4     AT 11,0  LEN 1 COLOR=RED
  INPUT DEL5     AT 12,0  LEN 1 COLOR=RED
  INPUT DEL6     AT 13,0  LEN 1 COLOR=RED
  INPUT DEL7     AT 14,0  LEN 1 COLOR=RED
  INPUT DEL8     AT 15,0  LEN 1 COLOR=RED
  INPUT DEL9     AT 16,0  LEN 1 COLOR=RED
  INPUT DEL10    AT 17,0  LEN 1 COLOR=RED

  INPUT MSG      AT 18,0  LEN 78 PROT BRIGHT COLOR=RED
  FIELD AT 20,0  LEN 34 PROT COLOR=RED           "THERE IS NO DELETION CONFIRMATION!"
  FIELD AT 21,0  LEN 34 PROT COLOR=BLUE          "PF9=Export Saves PF10=Import Saves"
  FIELD AT 21,35 LEN 37 PROT COLOR=WHITE         "(Existing saves are NOT overwritten.)"
  FIELD AT 22,0  LEN 40 PROT COLOR=BLUE          "ENTER=Apply D=Delete Save PF3=Exit PF5=Reload PF7=Back PF8=Foward"
  CURSOR         AT NIMPORT
ENDMAP
